// Helper function to check if a sequence is palindromic
function is_palindromic(seq: seq<int>): bool
    requires |seq| >= 0
{
    var n := |seq|;
    var i := 0;
    while i < n / 2
        invariant 0 <= i <= n / 2
        invariant forall j :: 0 <= j < i ==> seq[j] == seq[n - 1 - j]
    {
        if seq[i] != seq[n - 1 - i] {
            return false;
        }
        i := i + 1;
    }
    return true;
}

// Helper function to calculate the sum of elements in a sequence
function sum(seq: seq<int>): int
    requires |seq| >= 0
{
    var total := 0;
    var i := 0;
    while i < |seq|
        invariant 0 <= i <= |seq|
        invariant total == sum(seq[0..i])
    {
        total := total + seq[i];
        i := i + 1;
    }
    return total;
}

